    "template": "<div class=\"control-note max-file-upload\">\n  <p>{{ 'pilar.maximum' | pilarTranslate }} {{ maxFileSize }} {{ maxFileType.toUpperCase() }}</p>\n</div>\n<div class=\"form-upload-file-v2\" [class.flex-display]=\"_previewPosition !== 'bottom'\">\n  <button class=\"btn btn-primary form-control-file-upload\">\n    {{ inputLabel }} <input #file type=\"file\" [accept]=\"fileType\" [multiple]=\"multiple\" (change)=\"onFileChange($event)\">\n  </button>\n  <div class=\"file-list\" *ngIf=\"files.length > 0 && showPreview\">\n    <ng-container *ngFor=\"let file of files; let i = index\">\n      <p class=\"control-label file-name\"\n        [class.not-allowed]=\"((file?.fileSizeOver) || (file?.fileTypeNotMatch))\"\n        [class.left-marign]=\"_previewPosition !== 'bottom'\">\n        <span class=\"fa fa-trash table-cell\" aria-hidden=\"true\" (click)=\"onFileItemRemove(i)\"></span>\n        <span class=\"name table-cell\">{{ file?.name }}</span>\n        <span *ngIf=\"showFileSize\" class=\"table-cell\">{{sizes[i]}}</span>\n\n        <small *ngIf=\"(file?.fileSizeOver && files.length > 0)\" class=\"table-cell text-danger\">\n          {{ 'pilar.file size too large' | pilarTranslate }}\n        </small>\n\n        <small *ngIf=\"(file?.fileTypeNotMatch && files.length > 0)\" class=\"table-cell text-danger\">\n          {{ 'pilar.file type not allowed' | pilarTranslate }}\n        </small>\n      </p>\n    </ng-container>\n  </div>\n</div>",
