    "template": "<div *ngIf=\"limitOptions || searchOptions || checkboxColumn\" class=\"mobile-filter-container\">\n  <div class=\"limit-check-container\">\n    <ul>\n      <li class=\"mobile-checkbox-container\" *ngIf=\"checkboxColumn\">\n        <div class=\"gateway-rcb\">\n          <input\n            type=\"checkbox\"\n            [checked]=\"isAllRowsSelected\"\n            class=\"gateway-rcb-select\"\n            (change)=\"onRowSelect($event)\"/>\n          <label class=\"gateway-rcb-label\"></label>\n          <p>&nbsp;{{ 'pilar.all' | pilarTranslate }} &nbsp;&nbsp;</p>\n        </div>\n      </li>\n      <li *ngIf=\"limitOptions\" class=\"mobile-limit-container\">\n        <div class=\"limiting\">\n          <span\n            class=\"filter-select\"\n            (click)=\"onClickLimiting($event)\"\n          >{{ filterSelectedLimit }} {{ 'pilar.shown' | pilarTranslate }}</span>\n        </div>\n      </li>\n    </ul>\n  </div>\n  <div *ngIf=\"searchOptions\" class=\"mobile-search-container\">\n    <ul>\n      <li (click)=\"onClickSort($event)\">\n        <span class=\"ikon fa fa-sort\"></span>\n        <span>&nbsp;{{ 'pilar.sort' | pilarTranslate }} &nbsp;</span>\n      </li>\n      <li (click)=\"onClickSearch($event)\">\n        <span class=\"ikon fa\" [ngClass]=\"toogleSearch ? 'fa-times' : 'fa-search'\"></span>\n      </li>\n    </ul>\n  </div>\n  <div class=\"mobile-limit-overlay\" [ngClass]=\"toggleLimit ? '' : 'hide-limit-select'\">\n    <ol class=\"limit-item\">\n      <li\n        *ngFor=\"let limit of limitOptionsDropdown\"\n        (click)=\"onLimitChange(limit.v\n… (truncated)",
