    "template": "<div class=\"cell-action\">\n  <ng-container *ngFor=\"let action of beforeDetailActions\">\n    <ng-container *ngTemplateOutlet=\"actionTpl; context: { $implicit: action }\"></ng-container>\n  </ng-container>\n\n  <ng-container *ngFor=\"let action of additionalAction\">\n    <span class=\"action-icon icon-primary\" [uiiTooltip]=\"action.tooltip\">\n      <span [ngClass]=\"action.icon_class\" (click)=\"action.click(item)\"></span>\n    </span>\n  </ng-container>\n\n  <ng-container *ngIf=\"detailAction\">\n    <ng-container *ngTemplateOutlet=\"actionTpl; context: { $implicit: detailAction }\"></ng-container>\n  </ng-container>\n\n  <ng-container *ngFor=\"let action of afterDetailActions\">\n    <ng-container *ngTemplateOutlet=\"actionTpl; context: { $implicit: action }\"></ng-container>\n  </ng-container>\n\n  <span *ngIf=\"actionInValidation\"\n        class=\"action-icon icon-primary\"\n        (click)=\"onLeftClick('invalidate')\"\n        uiiTooltip=\"{{ 'pilar.cancel validation' | pilarTranslate }}\">\n    <span class=\"fa fa-lock\"></span>\n  </span>\n\n  <span *ngIf=\"auth?.canActivate\" class=\"action-icon i-on-off icon-primary\" uiiTooltip=\"{{ 'pilar.activation' | pilarTranslate }}\">\n    <uii-switch\n      [useOverlay]=\"true\"\n      [checked]=\"item.is_active === 1 || item.flag_aktif === 1\"\n      (changeEvent)=\"onLeftClick('activate', $event)\">\n    </uii-switch>\n  </span>\n</div>\n\n<ng-template #actionTpl let-action>\n  <ng-container *ngIf=\"shouldShow(action)\">\n\n    <span *ngIf=\"isContextEnabled(action.type); else noMenuAction\"\n      cla\n… (truncated)",
