    "text": "@Injectable({ providedIn: 'root' })\nexport class PilarTranslateService {\n  private currentLang: PilarLang = this.detectInitialLang();\n  private langChanges = new BehaviorSubject<PilarLang>(this.currentLang);\n\n  readonly onLangChange: Observable<PilarLang> = this.langChanges.asObservable();\n\n  get lang(): PilarLang {\n    return this.currentLang;\n  }\n\n  setLang(lang: PilarLang): void {\n    if (lang !== this.currentLang) {\n      this.currentLang = lang;\n      this.langChanges.next(lang);\n    }\n  }\n\n  instant(key: string): string {\n    const translations = dictionary[this.currentLang] || dictionary['id'];\n    return key in translations ? translations[key] : key;\n  }\n\n  private detectInitialLang(): PilarLang {\n    try {\n      const origin = typeof window !== 'undefined' ? window.location.origin : '';\n      const raw = localStorage.getItem(origin + CORE_LANG_STORAGE_KEY);\n      if (raw) {\n        const lang = JSON.parse(raw);\n        return lang === 'en' ? 'en' : 'id';\n      }\n    } catch (e) {\n    }\n    return 'id';\n  }\n}",
